using System.CommandLine;using System.Text.Json;using Cis.Abstractions;using Microsoft.Extensions.DependencyInjection;namespace Cis.Modules.Learn;public sealed class LearnModule:ICisModule{private static readonly JsonSerializerOptions J=new(JsonSerializerDefaults.Web){WriteIndented=true};public string Name=>"learn";public string Description=>"Collect evidence and govern improvement proposals through human review and canonical history.";public void RegisterServices(IServiceCollection s)=>s.AddSingleton<LearnService>();public void RegisterCommands(ICisCommandRegistry c,IServiceProvider p){var s=p.GetRequiredService<LearnService>();var r=new Command(Name,Description);r.Subcommands.Add(Simple("collect","Collect disposable improvement evidence.",s.Collect));r.Subcommands.Add(Simple("propose","Create derived proposals from collected evidence.",s.Propose));r.Subcommands.Add(Review(s));r.Subcommands.Add(WithId("apply","Apply an approved proposal to canonical history.",s.Apply));r.Subcommands.Add(Simple("history","List canonical applied-learning history.",s.History));c.Add(r);}private static Command Review(LearnService s){var c=new Command("review","Record a human proposal decision.");var id=new Argument<string>("proposal-id");var decision=Req("--decision");var reviewer=Req("--reviewer");var reason=Req("--reason");var repo=Repo();var f=Format();c.Arguments.Add(id);foreach(var o in new Option[]{decision,reviewer,reason,repo,f})c.Options.Add(o);c.SetAction(x=>Render(s.Review(x.GetValue(repo)!,x.GetValue(id)!,x.GetValue(decision)!,x.GetValue(reviewer)!,x.GetValue(reason)!),x.GetValue(f)!));return c;}private static Command WithId(string n,string d,Func<string,string,LearnResult>a){var c=new Command(n,d);var id=new Argument<string>("proposal-id");var r=Repo();var f=Format();c.Arguments.Add(id);c.Options.Add(r);c.Options.Add(f);c.SetAction(x=>Render(a(x.GetValue(r)!,x.GetValue(id)!),x.GetValue(f)!));return c;}private static Command Simple(string n,string d,Func<string,LearnResult>a){var c=new Command(n,d);var r=Repo();var f=Format();c.Options.Add(r);c.Options.Add(f);c.SetAction(x=>Render(a(x.GetValue(r)!),x.GetValue(f)!));return c;}private static int Render(LearnResult r,string f){if(f=="json")Console.WriteLine(JsonSerializer.Serialize(r,J));else if(f=="agent"){Console.WriteLine($"status={r.Status};exitCode={r.ExitCode};proposals={r.Proposals.Count};history={r.History.Count};applied={r.Applied.ToString().ToLowerInvariant()}");foreach(var e in r.Errors)Console.WriteLine($"error={e.Replace(';',',')}");}else if(f=="human"){Console.WriteLine($"Learning: {r.Status}; proposals={r.Proposals.Count}; history={r.History.Count}");foreach(var p in r.Proposals)Console.WriteLine($"- {p.Id}: {p.Status} - {p.Title}");foreach(var e in r.Errors)Console.WriteLine($"ERROR: {e}");}else return 2;return r.ExitCode;}private static Option<string>Req(string n)=>new(n){Required=true};private static Option<string>Repo()=>new("--repo"){DefaultValueFactory=_=>Directory.GetCurrentDirectory()};private static Option<string>Format()=>new("--format"){DefaultValueFactory=_=>"human"};}
